import{c as e,Q as o,j as d,m as i}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Overview — Using FinSight","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":null}'),a={name:"guide/overview.md"};function r(n,t,s,c,h,l){return o(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="overview-—-using-finsight" tabindex="-1">Overview — Using FinSight <a class="header-anchor" href="#overview-—-using-finsight" aria-label="Permalink to &quot;Overview — Using FinSight&quot;">​</a></h1><p>FinSight is organized around a handful of screens you will visit in any session. This section walks through each one — what it shows, where its numbers come from, and what to do next.</p><h2 id="the-daily-loop" tabindex="-1">The daily loop <a class="header-anchor" href="#the-daily-loop" aria-label="Permalink to &quot;The daily loop&quot;">​</a></h2><ol><li><strong>Today</strong> — check net worth, savings rate, and the one thing the Copilot thinks you should act on.</li><li><strong>Review</strong> — clear the needs-review queue: categorize, merge transfers, split joint purchases.</li><li><strong>Budget / Goals</strong> — nudge one envelope or make a contribution; see forecast update.</li><li><strong>Ask the Copilot</strong> when you want a plan, not just a total.</li></ol><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>For</th><th>Key source</th></tr></thead><tbody><tr><td><a href="/FinSight/guide/today">Today</a></td><td>Daily state</td><td><code>finsight-core::metrics</code> + last close</td></tr><tr><td><a href="/FinSight/guide/accounts">Accounts</a></td><td>Holdings and history</td><td><code>repos/accounts</code>, SimpleFIN sync runs</td></tr><tr><td><a href="/FinSight/guide/transactions">Transactions</a></td><td>Ledger detail</td><td><code>repos/transactions</code> + transfer/split logic</td></tr><tr><td><a href="/FinSight/guide/budget">Budget</a></td><td>Envelope plan</td><td><code>repos/budgets</code>, spending types</td></tr><tr><td><a href="/FinSight/guide/categories">Categories</a></td><td>Taxonomy &amp; guidance</td><td><code>repos/categories</code> + <code>spending/classify</code></td></tr><tr><td><a href="/FinSight/guide/recurring">Recurring</a></td><td>Subscriptions &amp; bills</td><td><code>subscriptions</code> + <code>recurring</code> detectors</td></tr><tr><td><a href="/FinSight/guide/goals">Goals</a></td><td>Targets &amp; compounding</td><td><code>repos/goals</code> + projection at 7%</td></tr><tr><td><a href="/FinSight/guide/reports">Reports</a></td><td>Monthly trends &amp; exports</td><td><code>metrics</code>, <code>custom_report</code>, <code>report_widgets</code></td></tr><tr><td><a href="/FinSight/guide/insights">Insights</a></td><td>Anomalies &amp; patterns</td><td><code>anomaly</code> + <code>agent_memory</code></td></tr><tr><td><a href="/FinSight/guide/cashflow">Cash Flow</a></td><td>Safe-to-spend &amp; calendar</td><td><code>forecast</code> + <code>cashflow</code></td></tr><tr><td><a href="/FinSight/guide/scenarios">Scenarios</a></td><td>What-if math</td><td>Deterministic finance tools via Copilot</td></tr><tr><td><a href="/FinSight/guide/recipes">Recipes</a></td><td>One-click fixes</td><td>Trusted recipe runner (<code>finsight-agent::recipe_runner</code>)</td></tr><tr><td><a href="/FinSight/guide/journey">Journey</a></td><td>Seven milestones</td><td>Wellness context + goal state</td></tr></tbody></table><p>Tip: amounts throughout the UI carry the <code>money</code> class so Privacy mode (eye icon) can blur them.</p><p>Next: <a href="/FinSight/guide/today">Today</a>.</p>',8)])])}const p=e(a,[["render",r]]);export{u as __pageData,p as default};
